/* Art-direct the crop: the band's aspect differs a lot per size, so shift the
   focal point to keep a complete subject (never a half-cut sun). */
html[data-k="0.85"] .photoband img { object-position: center 64%; }
html[data-k="0.28"] .photoband img { object-position: center 50%; }

