const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const sizes = [[1080,1350,'portrait'],[1200,1000,'wide'],[300,600,'sky']];
(async () => {
  const b = await chromium.launch();
  for (const [w,h,name] of sizes) {
    const p = await b.newPage({ viewport:{width:w,height:h} });
    await p.goto('file:///private/var/folders/hf/35wnqrnj2bbb1_llbg87zlt40000gn/T/vs-43a6479a7efacbab/flyer.html');
    await p.waitForTimeout(400);
    const r = await p.evaluate(() => {
      const out = {};
      out.k = +document.documentElement.dataset.k;
      out.fontInter = document.fonts.check('700 40px Inter');
      const st = document.getElementById('stage');
      const sr = st.getBoundingClientRect();
      out.stage = [Math.round(sr.width), Math.round(sr.height)];
      out.stageOverflow = [st.scrollWidth - st.clientWidth, st.scrollHeight - st.clientHeight];
      out.docOverflow = [document.documentElement.scrollWidth - window.innerWidth,
                         document.documentElement.scrollHeight - window.innerHeight];
      // bands full width?
      const band = document.querySelector('.photoband').getBoundingClientRect();
      const cta  = document.querySelector('.cta').getBoundingClientRect();
      out.bandX = [+band.left.toFixed(1), +band.right.toFixed(1), +band.height.toFixed(1)];
      out.ctaX  = [+cta.left.toFixed(1), +cta.right.toFixed(1)];
      out.vw = window.innerWidth;
      // photo aspect preserved?
      const img = document.querySelector('.photoband img');
      out.imgNatural = [img.naturalWidth, img.naturalHeight];
      out.imgBox = [+img.getBoundingClientRect().width.toFixed(1), +img.getBoundingClientRect().height.toFixed(1)];
      // candidate column centers
      out.candCenters = [...document.querySelectorAll('.cand')].map(c => {
        const b = c.getBoundingClientRect(); return +((b.left+b.right)/2).toFixed(1);
      });
      // text clipping / overflow of every text node holder
      out.clipped = [];
      document.querySelectorAll('h1,.name,.role,.cta span,.step span,.footer,.mono').forEach(e => {
        if (e.scrollWidth > e.clientWidth + 1 || e.scrollHeight > e.clientHeight + 1)
          out.clipped.push([e.className||e.tagName, e.scrollWidth, e.clientWidth, e.scrollHeight, e.clientHeight, e.textContent.slice(0,28)]);
      });
      // every visible element inside viewport bounds
      out.outside = [];
      document.querySelectorAll('#stage *').forEach(e => {
        const b = e.getBoundingClientRect();
        if (b.width===0&&b.height===0) return;
        if (b.left < -0.6 || b.top < -0.6 || b.right > window.innerWidth + 0.6 || b.bottom > window.innerHeight + 0.6)
          out.outside.push([e.className||e.tagName, +b.left.toFixed(1), +b.top.toFixed(1), +b.right.toFixed(1), +b.bottom.toFixed(1), (e.textContent||'').slice(0,24)]);
      });
      // vertical overlap between consecutive top-level sections
      const secs = [...document.getElementById('stage').children];
      out.overlaps = [];
      for (let i=0;i<secs.length-1;i++){
        const a=secs[i].getBoundingClientRect(), c=secs[i+1].getBoundingClientRect();
        if (c.top < a.bottom - 0.6) out.overlaps.push([secs[i].className, secs[i+1].className, +(a.bottom-c.top).toFixed(1)]);
      }
      out.gaps = secs.slice(0,-1).map((s,i)=> +(secs[i+1].getBoundingClientRect().top - s.getBoundingClientRect().bottom).toFixed(1));
      out.headlineLines = Math.round(document.querySelector('h1').getBoundingClientRect().height / (72*out.k*1.07));
      return out;
    });
    console.log('=== '+name+' '+w+'x'+h, JSON.stringify(r,null,1));
    await p.close();
  }
  await b.close();
})();
EOF
